  "tr": {
    "nisan": ["Hayatımızın en güzel gününde sizleri de aramızda görmekten mutluluk duyarız.", "Bir ömre ilk adımı atarken sevdiklerimizin yanımızda olmasını istiyoruz."],
    "dugun": ["Birlikte çıktığımız bu yolun ilk gününde sizleri de yanımızda görmek isteriz.", "Mutluluğumuzu paylaşmak için sizleri düğünümüze bekliyoruz."],
    "kina": ["Kına gecemizde neşemize ortak olmanızı dileriz.", "Gelinimizin kınasında sizleri de aramızda görmek isteriz."],
    "soz": ["Söz merasimimizde sizleri de aramızda görmekten mutluluk duyarız."],
    "sunnet": ["Oğlumuzun sünnet düğününde sizleri de aramızda görmekten onur duyarız.", "Delikanlımızın bu özel gününde sevincimize ortak olun."],
    "dogum": ["Yeni yaşımı sevdiklerimle kutlamak istiyorum. Sen de gel!", "Pastalar hazır, mumlar yanmak üzere. Seni de bekliyoruz!"],
    "baby": ["Minik mucizemizi beklerken bu sevinci sizinle paylaşmak istiyoruz."],
    "nikah": ["Dualarla başlayan bu yolda nikah törenimizde sizleri de aramızda görmekten mutluluk duyarız.", "Hayatımızı birleştireceğimiz nikah gününde sevdiklerimizin bizimle olmasını diliyoruz. Teşrifiniz bizi onurlandıracaktır."],
    "asker": ["Vatani görevine uğurlayacağımız evladımızın yanında olmanız bizi çok mutlu edecek. Dualarınızı bekliyoruz.", "Asker uğurlamamızda sizleri de aramızda görmek, bu özel günümüzü paylaşmak isteriz."],
    "mevlit": ["Aziz ruhuna ithaf edilen mevlit programımıza katılarak dualarınızla bizi yalnız bırakmamanızı rica ederiz.", "Hayırlara vesile olması dileğiyle okutacağımız mevlide, dualarınıza ortak olmak üzere sizleri bekliyoruz."],
    "mezuniyet": ["Emeklerimizin karşılığını aldığımız bu günde sevincimizi sizinle paylaşmak istiyoruz. Mezuniyetimize bekleriz!", "Yeni bir başlangıca adım atarken sizin de yanımızda olmanız en büyük mutluluğumuz olur."],
    "evacilisi": ["Yeni evimizde ilk çayı sizinle içmek istiyoruz. Kapımız size açık, bekleriz!", "Yeni yuvamızın bereketini sevdiklerimizle paylaşmak istiyoruz. Ev açılışımıza buyurun."],
    "iftar": ["Ramazanın bereketini paylaşmak, iftar sofrasında sizinle bir araya gelmek istiyoruz. Buyurun!", "Bu mübarek ayda sofranıza ortak olmanız bizi mutlu eder. İftar davetimize bekleriz."],
    "disbugdayi": ["Minik dişimizin çıkışını, buğdayımızla birlikte sevdiklerimizle kutlamak istiyoruz. Bekleriz!", "İlk dişin sevincini paylaşmak için sizleri küçük bir buğday şenliğine bekliyoruz."],
    "cinsiyet": ["Minik misafirimiz pembe mi, mavi mi? Bu büyük sürprizi birlikte öğrenelim!", "Bebeğimizin cinsiyetini sizinle birlikte öğrenmek istiyoruz. Heyecanımıza ortak olun!"],
    "yildonumu": ["Birlikte geçen yılların sevincini sizinle paylaşmak istiyoruz. Yıl dönümümüzde bizimle olun.", "Bir ömre değer yılları sevdiklerimizle kutlamak istiyoruz. Bekleriz!"],
    "bekarliga": ["Bekarlığa veda ediyoruz! Eğlencemize sen de katıl, unutulmaz bir gece olsun.", "Büyük günden önce son bir kutlama: Gel, birlikte eğlenelim!"],
    "kurumsal": ["Açılışımızı sizinle birlikte yapmaktan onur duyarız. Katılımınız bizim için çok değerli.", "Etkinliğimize katılımınızdan memnuniyet duyarız. Sizinle buluşmayı dört gözle bekliyoruz."],
