  "de": {
    "nisan": ["Wir freuen uns sehr, unsere Verlobung mit euch zu feiern.", "Auf unserem ersten Schritt in eine gemeinsame Zukunft möchten wir euch an unserer Seite haben."],
    "dugun": ["Wir trauen uns! Feiert mit uns den schönsten Tag unseres Lebens.", "Gemeinsam mit unseren Familien laden wir euch herzlich zu unserer Hochzeit ein."],
    "kina": ["Feiert mit uns einen Abend voller Henna, Musik und Freude."],
    "soz": ["Wir freuen uns, euch bei unserer Versprechensfeier zu sehen."],
    "sunnet": ["Wir würden uns freuen, den besonderen Tag unseres Sohnes mit euch zu feiern."],
    "dogum": ["Ich feiere mein neues Lebensjahr mit lieben Menschen. Sei dabei!"],
    "baby": ["Unser kleines Wunder ist unterwegs – feiert mit uns!"],
    "nikah": ["Wir freuen uns sehr, euch bei unserer Nikah-Zeremonie an unserer Seite zu haben, wenn wir unseren gemeinsamen Weg mit Segenswünschen beginnen.", "An dem Tag, an dem wir unser Leben verbinden, möchten wir die Menschen um uns haben, die uns am Herzen liegen."],
    "asker": ["Wir freuen uns, wenn ihr dabei seid, wenn wir unseren Sohn zum Wehrdienst verabschieden. Eure guten Wünsche begleiten ihn.", "Kommt zur Abschiedsfeier vor dem Beginn des Wehrdienstes und teilt diesen besonderen Tag mit uns."],
    "mevlit": ["Wir laden euch herzlich zum Mevlit zum liebevollen Gedenken ein und freuen uns, wenn ihr mit uns betet und diesen stillen Moment teilt.", "In der Hoffnung auf Segen und Gutes laden wir euch zu unserem Mevlit ein. Eure Anwesenheit und Gebete bedeuten uns viel."],
    "mezuniyet": ["Nach vielen Jahren harter Arbeit möchten wir diesen Tag mit euch feiern. Kommt zur Abschlussfeier!", "Beim Start in ein neues Kapitel würden wir uns freuen, euch an unserer Seite zu haben."],
    "evacilisi": ["Wir möchten den ersten Tee in unserem neuen Zuhause mit euch trinken. Unsere Tür steht offen, kommt vorbei!", "Die Freude über unser neues Zuhause teilen wir gern mit euch. Feiert mit uns die Einweihung!"],
    "iftar": ["Wir freuen uns, die Segnungen des Ramadan mit euch zu teilen und gemeinsam das Fasten zu brechen. Ihr seid herzlich eingeladen.", "In diesem gesegneten Monat möchten wir mit euch am Tisch zusammenkommen."],
    "disbugdayi": ["Unser Kleines hat den ersten Zahn bekommen, das feiern wir mit süßem Weizen. Seid dabei!", "Wir teilen die Freude über den ersten Zahn und laden euch zu einer kleinen, gemütlichen Feier ein."],
    "cinsiyet": ["Rosa oder Blau? Findet mit uns heraus, wer bald zu unserer Familie gehört!", "Wir möchten das Geschlecht unseres Babys mit euch zusammen enthüllen. Seid gespannt dabei!"],
    "yildonumu": ["Die gemeinsamen Jahre möchten wir mit euch feiern. Seid bei unserem Hochzeitstag dabei!", "Jahre, die ein Leben wert sind, feiern wir gern mit den Menschen, die uns wichtig sind."],
    "bekarliga": ["Der große Tag naht! Feier mit uns einen letzten unvergesslichen Abend.", "Eine letzte Party vor der Hochzeit: Komm dazu, wir machen es unvergesslich!"],
    "kurumsal": ["Wir freuen uns, unsere Eröffnung gemeinsam mit Ihnen zu feiern. Ihre Teilnahme bedeutet uns viel.", "Wir würden uns freuen, Sie bei unserer Veranstaltung begrüßen zu dürfen."],
    "diger": ["Wir freuen uns sehr, diesen besonderen Tag mit euch zu teilen."],
  },
  "ar": {
    "nisan": ["يسعدنا حضوركم ومشاركتنا فرحة خطوبتنا.", "ونحن نخطو أولى خطواتنا معًا، يسعدنا أن تكونوا إلى جانبنا."],
    "dugun": ["بكل الحب والفرح، ندعوكم لمشاركتنا حفل زفافنا.", "يتشرف أهلنا بدعوتكم لحضور حفل زفافنا، وحضوركم يتمم فرحتنا."],
    "kina": ["ندعوكم لمشاركتنا ليلة الحناء بأجوائها المبهجة."],
    "soz": ["يسعدنا حضوركم حفل الوعد."],
    "sunnet": ["يتشرف أهلنا بدعوتكم لمشاركتنا فرحة حفل ختان ابننا."],
    "dogum": ["أحتفل بعامي الجديد مع أحبائي، وحضورك يسعدني!"],
    "baby": ["ننتظر مولودنا الصغير، ويسعدنا أن نشارككم هذه الفرحة."],
    "nikah": ["نبدأ حياتنا معًا بالدعاء والبركة، ويسعدنا حضوركم حفل عقد قراننا.", "في يوم اقتران حياتنا، يشرفنا أن تكونوا بيننا، فحضوركم يزيدنا فرحًا."],
    "asker": ["يسعدنا حضوركم لتوديع ابننا قبل التحاقه بالخدمة العسكرية، ودعواتكم تهمنا كثيرًا.", "ندعوكم لمشاركتنا حفل الوداع قبل بدء الخدمة العسكرية."],
    "mevlit": ["ندعوكم لحضور مجلس المولد المهدى إلى روحه الطاهرة، ونرجو أن تشاركونا بدعائكم.", "رجاء الخير والبركة، ندعوكم لحضور مجلس المولد، وحضوركم ودعاؤكم محل تقديرنا."],
    "mezuniyet": ["بعد سنوات من الجهد، نود مشاركتكم فرحة التخرج، ويسعدنا حضوركم.", "ونحن نبدأ فصلًا جديدًا، يسعدنا أن تكونوا إلى جانبنا."],
    "evacilisi": ["نود أن نشرب أول كوب شاي في منزلنا الجديد معكم، وبابنا مفتوح لكم.", "يسعدنا أن نشارككم فرحة بيتنا الجديد، فتفضلوا بحضور حفل افتتاحه."],
    "iftar": ["يسرنا أن نشارككم بركة رمضان وأن نجتمع معكم على مائدة الإفطار، فأهلًا بكم.", "يسعدنا حضوركم مائدتنا في هذا الشهر الكريم."],
    "disbugdayi": ["ظهرت أول سن لصغيرنا، ويسعدنا أن نحتفل بها معكم على طبق القمح المحلّى.", "نشارككم فرحة أول سن لطفلنا، وندعوكم إلى احتفال صغير دافئ."],
    "cinsiyet": ["وردي أم أزرق؟ تعالوا لنكتشف معًا من سينضم إلى عائلتنا!", "نود أن نكشف عن جنس مولودنا معكم، فشاركونا الحماس."],
    "yildonumu": ["نود أن نحتفل معكم بسنوات عشناها معًا، ويسعدنا حضوركم ذكرى زواجنا.", "سنوات تعدل عمرًا، نحتفل بها مع أحبائنا، ونرجو أن تكونوا معنا."],
    "bekarliga": ["اقترب اليوم الكبير! انضموا إلينا في سهرة أخيرة لا تُنسى.", "احتفال أخير قبل الزفاف، فتعالوا لنجعله لا يُنسى."],
    "kurumsal": ["يشرفنا حضوركم حفل افتتاحنا، وحضوركم محل تقدير كبير.", "يسعدنا استقبالكم في فعاليتنا، ونتطلع إلى لقائكم."],
    "diger": ["يسعدنا حضوركم ومشاركتنا هذا اليوم المميز."],
  },
  "es": {
    "nisan": ["Nos hará muy felices contar contigo para celebrar nuestro compromiso.", "Al dar el primer paso hacia nuestro para siempre, queremos tenerte a nuestro lado."],
    "dugun": ["Junto a nuestras familias, te invitamos a celebrar el día de nuestra boda.", "Será un honor contar con tu presencia en el primer día de nuestro camino juntos."],
    "kina": ["Acompáñanos en una noche de henna, música y alegría."],
    "soz": ["Nos encantará verte en nuestra ceremonia de promesa."],
    "sunnet": ["Será un honor que celebres con nosotros el día tan especial de nuestro hijo."],
    "dogum": ["Voy a celebrar otro año de vida con la gente que quiero. ¡Ven a festejar conmigo!"],
    "baby": ["Nuestro pequeño milagro ya viene en camino y nos encantaría celebrarlo contigo."],
    "nikah": ["Al comenzar nuestra vida juntos con oraciones y bendiciones, nos hará muy felices tenerte en nuestra ceremonia de nikah.", "Será un honor compartir el día en que unimos nuestras vidas con las personas que más queremos."],
    "asker": ["Nos encantaría que nos acompañes a despedir a nuestro ser querido antes de su servicio militar. Tus buenos deseos significan mucho para nosotros.", "Acompáñanos en una despedida muy sentida antes de que comience su servicio militar."],
    "mevlit": ["Te invitamos con cariño a acompañarnos en oración en el mevlit que ofrecemos en memoria de un ser querido, y a compartir esta reunión tranquila.", "Con la esperanza de recibir bendiciones y bien, te invitamos a nuestro mevlit; te agradeceremos tu presencia y tus oraciones."],
    "mezuniyet": ["Después de años de esfuerzo, queremos compartir este día contigo. ¡Ven a celebrar la graduación!", "Al comenzar un nuevo capítulo, tenerte a nuestro lado significaría muchísimo."],
    "evacilisi": ["Nos encantaría tomar el primer té en nuestra casa nueva contigo. ¡Las puertas están abiertas, ven!", "Queremos compartir la alegría de nuestro nuevo hogar con quienes queremos. Acompáñanos en la inauguración."],
    "iftar": ["Nos alegrará compartir las bendiciones del Ramadán y romper el ayuno juntos. Estás cordialmente invitado.", "Nos hará felices reunirnos contigo en la mesa en este mes bendito."],
    "disbugdayi": ["¡Llegó el primer diente de nuestro pequeño! Queremos celebrarlo con un plato de trigo dulce. ¡Acompáñanos!", "Compartimos la alegría del primer dientecito y te invitamos a una celebración íntima y acogedora."],
